            "database": {
                "image": "postgres:16",
                "environment": {"POSTGRES_PASSWORD": "test-only"},
                "healthcheck": {"test": ["CMD-SHELL", "pg_isready -U postgres"]},
                "ports": ["5432:5432"],
                "expose": ["5432"],
                "networks": ["backend"],
                "volumes": [
                    "database-data:/var/lib/postgresql/data",
                    {"type": "volume", "source": "database-cache", "target": "/cache"},
                    {"type": "tmpfs", "target": "/tmp"},
